-- tools/sql/0050/preflight.sql  — READ-ONLY. Run before migration 0050 on the target database.
-- Every row says what it checked, what it expects, what it found, and PASS or FAIL. Do not apply 0050 unless every REQUIRED row passes.
-- Rows marked INFO are for you to read (they do not block). Nothing here writes.
-- Counts marked "hosted dev" were observed on 2026-10-15; a different number is not an error, but tell the reviewer why.
WITH checks(sort, severity, name, expected, actual, pass) AS (
  VALUES
  (10, 'REQUIRED', 'role can bypass row-level security (the migration inserts into forced-RLS tables)', 'true',
     (SELECT rolbypassrls::text FROM pg_roles WHERE rolname = current_user),
     (SELECT rolbypassrls FROM pg_roles WHERE rolname = current_user)),
  (11, 'INFO', 'executing role / superuser flag', 'postgres / false on Supabase',
     (SELECT current_user || ' / ' || rolsuper::text FROM pg_roles WHERE rolname = current_user), true),
  (12, 'INFO', 'server version', 'PostgreSQL 17.x on hosted dev', split_part(version(), ' on ', 1), true),
  (20, 'REQUIRED', 'platform tenant id is free', '0', (SELECT count(*)::text FROM app.tenant WHERE id = 'ten_01M4ZG67WTS51Q0XN7F1Y9CCYG'),
     (SELECT count(*) = 0 FROM app.tenant WHERE id = 'ten_01M4ZG67WTS51Q0XN7F1Y9CCYG')),
  (21, 'REQUIRED', 'platform tenant slug is free', '0', (SELECT count(*)::text FROM app.tenant WHERE slug = 'platform-operations'),
     (SELECT count(*) = 0 FROM app.tenant WHERE slug = 'platform-operations')),
  (22, 'REQUIRED', 'platform role ids and codes are free', '0',
     (SELECT count(*)::text FROM app.role WHERE id IN ('role_01M4ZG67WYKTMHNAX6RB8RYQYQ','role_01M4ZG67WYKTMHNAX6RB8RYQYR') OR code IN ('ROLE-PLATFORM-SUPERADMIN','ROLE-PLATFORM-SUPPORT')),
     (SELECT count(*) = 0 FROM app.role WHERE id IN ('role_01M4ZG67WYKTMHNAX6RB8RYQYQ','role_01M4ZG67WYKTMHNAX6RB8RYQYR') OR code IN ('ROLE-PLATFORM-SUPERADMIN','ROLE-PLATFORM-SUPPORT'))),
  (23, 'REQUIRED', 'platform organisation and branch ids are free', '0',
     (SELECT (SELECT count(*) FROM app.organisation WHERE id = 'org_01M4ZG67WZ2ZPNJ361KHB1DGK6') + (SELECT count(*) FROM app.branch WHERE id = 'br_01M4ZJ8H51XBQ0A3RWZSBVRZAP'))::text,
     (SELECT (SELECT count(*) FROM app.organisation WHERE id = 'org_01M4ZG67WZ2ZPNJ361KHB1DGK6') + (SELECT count(*) FROM app.branch WHERE id = 'br_01M4ZJ8H51XBQ0A3RWZSBVRZAP')) = 0),
  (24, 'REQUIRED', 'the two new functions do not exist yet', 'none',
     coalesce((SELECT string_agg(proname, ',') FROM pg_proc WHERE pronamespace = 'app'::regnamespace AND proname IN ('is_platform_realm','platform_tenant_user_counts')), 'none'),
     NOT EXISTS (SELECT 1 FROM pg_proc WHERE pronamespace = 'app'::regnamespace AND proname IN ('is_platform_realm','platform_tenant_user_counts'))),
  (30, 'REQUIRED', 'constraint tenant_tenant_type_check exists (the migration drops it by name)', '1',
     (SELECT count(*)::text FROM pg_constraint WHERE conrelid = 'app.tenant'::regclass AND conname = 'tenant_tenant_type_check'),
     EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'app.tenant'::regclass AND conname = 'tenant_tenant_type_check')),
  (31, 'REQUIRED', 'constraint support_access_grant_status_check exists', '1',
     (SELECT count(*)::text FROM pg_constraint WHERE conrelid = 'app.support_access_grant'::regclass AND conname = 'support_access_grant_status_check'),
     EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'app.support_access_grant'::regclass AND conname = 'support_access_grant_status_check')),
  (32, 'REQUIRED', 'constraint data_correction_request_status_check exists', '1',
     (SELECT count(*)::text FROM pg_constraint WHERE conrelid = 'app.data_correction_request'::regclass AND conname = 'data_correction_request_status_check'),
     EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'app.data_correction_request'::regclass AND conname = 'data_correction_request_status_check')),
  (33, 'REQUIRED', 'policy support_access_grant.tenant_isolation exists (the migration replaces it)', '1',
     (SELECT count(*)::text FROM pg_policies WHERE schemaname = 'app' AND tablename = 'support_access_grant' AND policyname = 'tenant_isolation'),
     EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'app' AND tablename = 'support_access_grant' AND policyname = 'tenant_isolation')),
  (34, 'REQUIRED', 'none of the migration''s new policies exist yet', 'none',
     coalesce((SELECT string_agg(tablename || '.' || policyname, ',') FROM pg_policies WHERE schemaname = 'app' AND policyname IN ('platform_read','flag_read','flag_insert','flag_update','master_read','master_insert','master_update','grant_tenant_read','grant_platform_request','grant_tenant_decide')), 'none'),
     NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'app' AND policyname IN ('platform_read','flag_read','flag_insert','flag_update','master_read','master_insert','master_update','grant_tenant_read','grant_platform_request','grant_tenant_decide'))),
  (35, 'REQUIRED', 'the new columns are not there yet (support_access_grant, data_correction_request)', '0',
     (SELECT count(*)::text FROM information_schema.columns WHERE table_schema = 'app' AND ((table_name = 'support_access_grant' AND column_name IN ('scope','incident_ref','starts_at')) OR (table_name = 'data_correction_request' AND column_name IN ('justification','script_ref','target_entity','change_description','dry_run_diff_key','dry_run_diff','requested_by','executed_at','executor_identity')))),
     (SELECT count(*) = 0 FROM information_schema.columns WHERE table_schema = 'app' AND ((table_name = 'support_access_grant' AND column_name IN ('scope','incident_ref','starts_at')) OR (table_name = 'data_correction_request' AND column_name IN ('justification','script_ref','target_entity','change_description','dry_run_diff_key','dry_run_diff','requested_by','executed_at','executor_identity'))))),
  (40, 'REQUIRED', 'permission codes the migration grants exist in the catalogue', '7',
     (SELECT count(*)::text FROM app.permission WHERE code IN ('platform.console','platform.flags','platform.master_data','platform.jobs','platform.support_access','platform.release','audit.read')),
     (SELECT count(*) = 7 FROM app.permission WHERE code IN ('platform.console','platform.flags','platform.master_data','platform.jobs','platform.support_access','platform.release','audit.read'))),
  (41, 'REQUIRED', 'the helper functions app_tenant() and enable_tenant_rls exist', '2',
     (SELECT count(*)::text FROM pg_proc WHERE pronamespace = 'app'::regnamespace AND proname IN ('app_tenant','enable_tenant_rls')),
     (SELECT count(*) = 2 FROM pg_proc WHERE pronamespace = 'app'::regnamespace AND proname IN ('app_tenant','enable_tenant_rls'))),
  (42, 'REQUIRED', 'role dsa_app exists', '1', (SELECT count(*)::text FROM pg_roles WHERE rolname = 'dsa_app'), EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'dsa_app')),
  (50, 'INFO', 'operator grants that will be DELETED from customer-tenant roles (hosted dev: 30)', '30',
     (SELECT count(*)::text FROM app.role_permission WHERE permission_code IN ('platform.console','platform.flags','platform.master_data','platform.jobs','platform.support_access','platform.release') AND tenant_id <> 'ten_01M4ZG67WTS51Q0XN7F1Y9CCYG'),
     (SELECT count(*) FROM app.role_permission WHERE permission_code IN ('platform.console','platform.flags','platform.master_data','platform.jobs','platform.support_access','platform.release') AND tenant_id <> 'ten_01M4ZG67WTS51Q0XN7F1Y9CCYG') = 30),
  (51, 'INFO', 'which roles they come from', 'hosted dev: ORG-OWNER and TENANT-ADMIN of Alpha and Beta, TENANT-ADMIN of Demo DSA',
     (SELECT string_agg(t.legal_name || ' / ' || r.code, '; ' ORDER BY t.legal_name, r.code) FROM (SELECT DISTINCT role_id, tenant_id FROM app.role_permission WHERE permission_code LIKE 'platform.%') g JOIN app.role r ON r.id = g.role_id JOIN app.tenant t ON t.id = g.tenant_id), true),
  (52, 'INFO', 'accounts that will LOSE platform.* (hosted dev: 7 accounts, 5 people)', '',
     (SELECT string_agg(DISTINCT u.email, ', ') FROM app.user_role_assignment a JOIN app.app_user u ON u.id = a.user_id JOIN app.role_permission rp ON rp.role_id = a.role_id WHERE rp.permission_code LIKE 'platform.%' AND a.effective_range @> now()), true),
  (53, 'INFO', 'data_correction.approve holders: UNCHANGED by this migration', '5 roles on hosted dev',
     (SELECT count(*)::text FROM app.role_permission WHERE permission_code = 'data_correction.approve'), true),
  (60, 'INFO', 'existing rows that are kept: support / correction / flags / master data', 'hosted dev: 1 / 1 / 5 / 9',
     (SELECT (SELECT count(*) FROM app.support_access_grant) || ' / ' || (SELECT count(*) FROM app.data_correction_request) || ' / ' || (SELECT count(*) FROM app.feature_flag) || ' / ' || (SELECT count(*) FROM app.master_data_item)), true),
  (61, 'INFO', 'audit_event rows referencing a platform tenant (a rollback cannot delete the tenant once there are any)', '0', (SELECT count(*)::text FROM app.audit_event WHERE tenant_id = 'ten_01M4ZG67WTS51Q0XN7F1Y9CCYG'), true),
  (62, 'INFO', 'default privileges that may auto-grant new functions to API roles', 'read: the migration revokes them explicitly',
     coalesce((SELECT string_agg(defaclrole::regrole::text || ' ' || defaclobjtype::text || ' ' || defaclacl::text, ' ; ') FROM pg_default_acl), 'none'), true),
  (63, 'INFO', 'migration history table', 'none on hosted dev (it was built with direct SQL, so there is nothing to repair)',
     coalesce((SELECT string_agg(table_schema || '.' || table_name, ', ') FROM information_schema.tables WHERE table_name = 'schema_migrations' AND table_schema NOT IN ('auth','realtime','storage')), 'none'), true)
)
SELECT severity, name, expected, actual, CASE WHEN pass THEN 'PASS' ELSE 'FAIL' END AS result
  FROM checks ORDER BY sort;
